// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, address ownerCandidate) public {
        vm.assume(ownerCandidate != address(0));
        amount = bound(amount, 0, 1 ether);

        AcceptingCallee callee = new AcceptingCallee();

        vm.deal(address(this), amount);

        bool ok;
        try c.Command(address(callee), abi.encodeWithSelector(AcceptingCallee.hit.selector)) { ok = true; }
        catch { ok = false; }

        vm.assume(ok);

        assertTrue(c.Owner() == address(this));
    }
}

contract AcceptingCallee {
    event Hit(address sender, uint256 value);
    fallback() external payable {
        emit Hit(msg.sender, msg.value);
    }
    receive() external payable {
        emit Hit(msg.sender, msg.value);
    }
    function hit() external payable {}
}
